def f(n):
    """
    Calculates f(n), the odd part of n.
    f(n) = n / 2^m where 2^m is the highest power of 2 dividing n.
    """
    if n <= 0:
        raise ValueError("n must be positive")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(v, u):
    """
    Checks if f(u+k+v) - f(u+k) is a multiple of 4 for all k=0, 1, ..., v-1.
    """
    for k in range(v):
        diff = f(u + k + v) - f(u + k)
        if diff % 4 != 0:
            return False
    return True

v_values = [1, 2, 3, 4]
u_values = range(1, 11)
successful_pairs = []

for v in v_values:
    for u in u_values:
        if check_condition(v, u):
            successful_pairs.append((v, u))

print("Successful (v, u) pairs:")
for pair in successful_pairs:
